export const BECOMES_FAMILY = "Clucap Becomes";
let becomesFont: Promise<unknown> | undefined;
export const loadBecomesFont = () => becomesFont ??= (async () => {
  const face = new FontFace(BECOMES_FAMILY, `url(${JSON.stringify(staticFile("becomes-notes/Becomes Notes.ttf"))})`, { weight: "400" });
  document.fonts.add(await face.load());
})().catch(() => { becomesFont = undefined; });
let inkCanvas: CanvasRenderingContext2D | null = null;
const measureNative = (text: string, size: number, weightPadding: number) => {
  inkCanvas ??= document.createElement("canvas").getContext("2d");
  const ctx = inkCanvas;
  if (!ctx) return { letters: [], native: true, inkLeft: 0, width: text.length * size * .5, ascent: size * .8, descent: size * .2 };
  ctx.font = `400 ${size}px "${BECOMES_FAMILY}"`;
  const m = ctx.measureText(text);
  const left = Number.isFinite(m.actualBoundingBoxLeft) ? m.actualBoundingBoxLeft : 0;
  const right = Number.isFinite(m.actualBoundingBoxRight) ? m.actualBoundingBoxRight : m.width;
  return { letters: [], native: true, inkLeft: -left * 1000 / size - weightPadding * 1000 / size,
    width: Math.max(1, left + right) + weightPadding * 2,
    ascent: Math.max(1, m.actualBoundingBoxAscent) + weightPadding, descent: Math.max(0, m.actualBoundingBoxDescent) + weightPadding };
};

/** A word in a script without pen strokes, written in by a sweep from left to right. */
const NativeWriting: React.FC<{ text: string; x: number; baseline: number; size: number; width: number; ascent: number; descent: number;
  inkLeft: number; progress: number; clipId: string }> = ({ text, x, baseline, size, width, ascent, descent, inkLeft, progress, clipId }) => {
  if (progress <= 0) return null;
  return <>
    <defs><clipPath id={clipId}><rect x={x - size * .2} y={baseline - ascent - size * .3} width={(width + size * .4) * clamp01(progress)}
      height={ascent + descent + size * .6} /></clipPath></defs>
    <text x={x - inkLeft * size / 1000} y={baseline} fontFamily={`"${BECOMES_FAMILY}"`} fontSize={size}
      clipPath={progress < 1 ? `url(#${clipId})` : undefined}>{text}</text>
  </>;
};

export const measureBecomesWord = (text: string, size: number, weightPadding = 0) => {
  if (isComplexScript(text)) return measureNative(text, size, weightPadding);
  let advance = 0; let left = Infinity; let right = -Infinity;
  let ascent = 0; let descent = 0;
  const letters = [...fontText(text)].map(character => {
    const glyph = GLYPHS[character];
    const x = advance;
    if (glyph.d) {
      left = Math.min(left, x + glyph.b[0]); right = Math.max(right, x + glyph.b[2]);
      ascent = Math.max(ascent, glyph.b[3]); descent = Math.max(descent, -glyph.b[1]);
    }
    advance += glyph.a;
    return { glyph, x };
  });
  if (!Number.isFinite(left)) { left = 0; right = advance; }
  return { letters, native: false, inkLeft: left - weightPadding * 1000 / size,
    width: Math.max(1, (right - left) * size / 1000) + weightPadding * 2,
    ascent: ascent * size / 1000 + weightPadding, descent: descent * size / 1000 + weightPadding };
};
const measureWord = measureBecomesWord;

type NoteCue = { id: string; words: Word[]; startMs: number; endMs: number;
  accentId?: string; underline: boolean; nameIds: string[] };
const makeCues = (words: Word[]): NoteCue[] => {
  const groups: Word[][] = []; let group: Word[] = []; let lastSolo = -Infinity;
  const flush = () => { if (group.length) groups.push(group); group = []; };
  for (const word of words) {
    const previous = group[group.length - 1];
    const isolate = !word.event && (word.emphasis || solitary.has(clean(word.text))) &&
      word.endMs - word.startMs >= 280 && word.startMs - lastSolo > 3500;
    if (previous && (previous.pageBreakAfter || /[.!?]["'”’)]?$/u.test(previous.text) ||
      word.startMs - previous.endMs > 340 || wordCount(group) >= 5 ||
      textLength([...group, word].map(w => w.text).join(" ")) > 32 || word.endMs - group[0].startMs > 2300)) flush();
    if (isolate) { flush(); groups.push([word]); lastSolo = word.startMs; }
    else group.push(word);
  }
  flush();
  return groups.map((entries, i) => {
    // Keep a two-part proper name together and let it carry the emphasis.
    const names = entries.filter((w, j) => !w.event && /^[A-Z][a-z]{2,}/.test(w.text) && !fillers.has(clean(w.text)) &&
      (j > 0 ||
       j + 1 < entries.length && /^[A-Z][a-z]{2,}/.test(entries[j + 1].text)));
    const ranked = [...entries].sort((a, b) => salience(b) - salience(a));
    // Prefer explicit emphasis and meaningful words, including ordinary phrases
    // outside the reference transcript's keyword list.
    const accent = names[0] ?? ranked.find(word => !word.event &&
      (word.emphasis || !fillers.has(clean(word.text)) && clean(word.text).length >= 3));
    const underline = Boolean(accent);
    return { id: `notes-${entries[0].id}`, words: entries, startMs: entries[0].startMs,
      endMs: Math.min(Math.max(...entries.map(w => w.endMs)) + 260, groups[i + 1]?.[0].startMs ?? Infinity),
      accentId: accent?.id, underline, nameIds: names.map(w => w.id) };
  });
};

const layoutCue = (cue: NoteCue, canvasHeight: number, fontSize: number, positionY: number, widthFraction: number) => {
  const build = (base: number) => {
    const solo = cue.words.length === 1;
    const measured = cue.words.map(word => {
      const highlighted = word.id === cue.accentId || cue.nameIds.includes(word.id);
      const size = base * (solo ? 1.5 : highlighted ? 1.32 : 1);
      return { word, size, highlighted, ...measureWord(word.text, size, highlighted ? .7 : 0) };
    });
    const gap = base * .23; const maxWidth = 720 * widthFraction;
    const lines: typeof measured[] = [[]]; let used = 0;
    measured.forEach(item => {
      const separateName = cue.nameIds.length > 0 && item.word.id === cue.nameIds[0] && lines[lines.length - 1].length > 0;
      if (used && (used + gap + item.width > maxWidth || separateName)) { lines.push([]); used = 0; }
      const line = lines[lines.length - 1]; line.push(item); used += item.width + (line.length > 1 ? gap : 0);
    });
    const widths = lines.map(line => line.reduce((sum, item) => sum + item.width, 0) + Math.max(0, line.length - 1) * gap);
    const metrics = lines.map(line => ({ ascent: Math.max(...line.map(item => item.ascent)),
      descent: Math.max(...line.map(item => item.descent +
        (cue.underline && item.highlighted ? item.size * .16 + 3 : 0))) }));
    const heights = metrics.map(m => Math.max(base * 1.13, m.ascent + m.descent + base * .18));
    const totalHeight = heights.reduce((sum, value) => sum + value, 0);
    let top = Math.max(12, Math.min(canvasHeight - totalHeight - 12, canvasHeight * positionY - totalHeight / 2));
    const items = lines.flatMap((line, row) => {
      let x = (720 - widths[row]) / 2;
      const baseline = top + (heights[row] - metrics[row].ascent - metrics[row].descent) / 2 + metrics[row].ascent;
      const result = line.map(item => {
        const placed = { ...item, x, baseline, row }; x += item.width + gap; return placed;
      });
      top += heights[row]; return result;
    });
    return { items, totalHeight, fits: lines.length <= 2 && Math.max(...widths) <= maxWidth && totalHeight < canvasHeight * .45 };
  };
  let size = fontSize; let layout = build(size);
  while (!layout.fits && size > 16) { size -= 1; layout = build(size); }
  return { ...cue, items: layout.items, totalHeight: layout.totalHeight };
};

const WrittenGlyph: React.FC<{ glyph: Glyph; progress: number; maskId: string }> = ({ glyph, progress, maskId }) => {
  if (progress <= 0 || !glyph.d) return null;
  if (progress >= 1 || !glyph.s.length) return <path d={glyph.d} />;
  const total = glyph.s.reduce((sum, stroke) => sum + stroke.l, 0);
  let covered = 0;
  return <>
    <defs><mask id={maskId} maskUnits="userSpaceOnUse" x={glyph.b[0] - 150} y={-glyph.b[3] - 150}
      width={glyph.b[2] - glyph.b[0] + 300} height={glyph.b[3] - glyph.b[1] + 300}
      style={{ maskType: "luminance" }}>
      {glyph.s.map((stroke, i) => {
        const local = clamp01((progress * total - covered) / Math.max(1, stroke.l)); covered += stroke.l;
        return local > 0 ? <path key={i} d={stroke.d} fill="none" stroke="white" strokeWidth={stroke.w}
          strokeLinecap="round" strokeLinejoin="round" pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - local} /> : null;
      })}
    </mask></defs>
    <path d={glyph.d} mask={`url(#${maskId})`} />
  </>;
};

/** Reusable handwriting renderer; positions match measureBecomesWord exactly. */
export const BecomesWordWriting: React.FC<{ text: string; x: number; baseline: number; size: number;
  progress: number; maskPrefix: string }> = ({ text, x, baseline, size, progress, maskPrefix }) => {
  const measured = measureBecomesWord(text, size);
  const count = measured.letters.length;
  if (measured.native) return <NativeWriting text={text} x={x} baseline={baseline} size={size} width={measured.width}
    ascent={measured.ascent} descent={measured.descent} inkLeft={measured.inkLeft} progress={progress} clipId={`${maskPrefix}-native`} />;
  return <>{measured.letters.map(({ glyph, x: letterX }, index) => <g key={index}
    transform={`translate(${x + (letterX - measured.inkLeft) * size / 1000} ${baseline}) scale(${size / 1000})`}>
    <WrittenGlyph glyph={glyph} progress={clamp01(progress * (count * .86 + .14) - index * .86)}
      maskId={`${maskPrefix}-${index}`} />
  </g>)}</>;
};

/** One self-contained handwritten style, with deterministic pen strokes and no font-loading delay. */
export const BecomesNotes: React.FC<BecomesNotesProps> = ({ sourceConfig = DEFAULT_SOURCE, styleConfig, presentationConfig, reducedMotion = false }) => {
  const frame = useCurrentFrame(); const { width, height, fps } = useVideoConfig();
  const now = frame * 1000 / fps; const canvasHeight = height * 720 / width;
  const onLayout = presentationConfig?.onLayout ?? styleConfig?.onLayout;
  // An explicit styleConfig value wins so the preview card can run the real
  // word animation while onLayout keeps reporting the settled height.
  const naturalWrap = styleConfig?.naturalWrap ?? !!presentationConfig?.onLayout;
  const baseSize = Number.isFinite(styleConfig?.fontSize) ? Math.max(16, Math.min(160, styleConfig!.fontSize!)) : 58;
  const positionY = Number.isFinite(styleConfig?.positionY) ? Math.max(.1, Math.min(.9, styleConfig!.positionY!)) : naturalWrap ? .5 : .73;
  const maxWidth = Number.isFinite(styleConfig?.maxWidth) ? Math.max(.3, Math.min(.94, styleConfig!.maxWidth!)) : 614 / 720;
  const uid = `becomes-${useId().replace(/[^a-zA-Z0-9]/g, "")}`;
  const words = useMemo(() => normalizeWords(sourceConfig).words, [sourceConfig]);
  // Words in other scripts are set in the Becomes Notes font family, which has to be loaded first.
  const native = useMemo(() => words.some(word => isComplexScript(word.text)), [words]);
  const [fontReady, setFontReady] = useState(false);
  const { delayRender, continueRender } = useDelayRender();
  useLayoutEffect(() => {
    if (!native) return;
    const handle = delayRender("Loading the Becomes Notes font");
    let live = true;
    void loadBecomesFont().then(() => { if (live) setFontReady(true); }).finally(() => continueRender(handle));
    return () => { live = false; };
  }, [native, delayRender, continueRender]);
  const cues = useMemo(() => !native || fontReady ? makeCues(words).map(cue =>
    layoutCue(cue, canvasHeight, baseSize, positionY, maxWidth)) : [], [words, native, fontReady, canvasHeight, baseSize, positionY, maxWidth]);
  useLayoutEffect(() => {
    if (!onLayout || !cues.length) return;
    const maxHeight = Math.max(...cues.map(c => (c as any).totalHeight || 90));
    onLayout(maxHeight * width / 720);
  }, [onLayout, cues, width]);
  const index = cues.findIndex(cue => now >= cue.startMs && now < cue.endMs);
  const cue = cues[index] ?? (naturalWrap ? cues[0] : undefined);
  useCueMotion(cue?.startMs, cue?.endMs);
  const next = cues[index + 1];
  const fade = cue && (!next || next.startMs > cue.endMs + 30) && !reducedMotion ? ease((cue.endMs - now) / 100) : 1;
  // The writing takes the text color picked for it, and the underline the key word color.
  const ink = solid(presentationConfig?.paints?.rest) ?? "#fffdf5", underline = solid(presentationConfig?.paints?.main) ?? "#f17d54";
  const background = sourceConfig.background;
  const backgroundSrc = background?.src ? /^(https?:|data:|blob:|\/)/i.test(background.src) ? background.src : staticFile(background.src) : undefined;
  return <AbsoluteFill style={{ backgroundColor: presentationConfig?.backgroundColor ?? "#202624", pointerEvents: "none", overflow: "hidden" }}>
    {backgroundSrc ? background?.kind === "image" ? <Img src={backgroundSrc}
      style={{ width: "100%", height: "100%", objectFit: "cover" }} /> :
      <SourceVideo src={backgroundSrc} muted={background?.muted ?? false} volume={background?.volume ?? 1}
        style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : null}
    {backgroundSrc ? <AbsoluteFill style={{ background: "linear-gradient(to top, rgba(0,0,0,.28), transparent 58%)" }} /> : null}
    {cue ? <svg width={width} height={height} viewBox={`0 0 720 ${canvasHeight}`} role="img"
      aria-label={cue.words.map(word => word.text).join(" ")} style={{ position: "absolute", inset: 0 }}>
      <defs>
        <filter id={`${uid}-emphasis`} x="-100%" y="-100%" width="300%" height="300%" colorInterpolationFilters="sRGB">
          <feMorphology in="SourceAlpha" operator="dilate" radius="0.65" result="weight" />
          <feGaussianBlur in="weight" stdDeviation="0.8" result="halo" />
          <feFlood floodColor="#fff6df" floodOpacity="0.16" /><feComposite in2="halo" operator="in" result="glow" />
          <feFlood floodColor={ink} /><feComposite in2="weight" operator="in" result="body" />
          <feMerge><feMergeNode in="glow" /><feMergeNode in="body" /><feMergeNode in="SourceGraphic" /></feMerge>
        </filter>
      </defs>
      <g opacity={fade} fill={ink}>
        {cue.items.map(item => {
          const available = Math.max(1, cue.endMs - item.word.startMs - 65);
          const duration = Math.min(available, Math.max(140, Math.min(440, (item.word.endMs - item.word.startMs) * .9)));
          const progress = naturalWrap || reducedMotion ? 1 : clamp01((now - item.word.startMs) / duration);
          if (progress <= 0 && !naturalWrap) return null;
          const count = item.letters.length;
          const nameItems = cue.items.filter(other => cue.nameIds.includes(other.word.id) && other.row === item.row);
          const lastName = nameItems[nameItems.length - 1];
          const underlineHere = cue.underline && (lastName ? item.word.id === lastName.word.id : item.word.id === cue.accentId);
          const underlineWord = lastName?.word ?? item.word;
          const underlineDuration = Math.max(80, Math.min(160, (underlineWord.endMs - underlineWord.startMs) * .5));
          const underlineStart = Math.max(underlineWord.startMs,
            Math.min(underlineWord.endMs - underlineDuration, underlineWord.startMs + duration * .4));
          const draw = naturalWrap || reducedMotion ? 1 : ease((now - underlineStart) / underlineDuration);
          const lineX = nameItems[0]?.x ?? item.x;
          const lineWidth = item.x + item.width - lineX;
          const inkBottom = Math.max(item.descent, ...nameItems.map(other => other.descent));
          const lineY = item.baseline + inkBottom + item.size * .07;
          return <g key={item.word.id} data-notes-word={item.word.id}>
            <g filter={item.highlighted ? `url(#${uid}-emphasis)` : undefined}>
            {item.native ? <NativeWriting text={item.word.text} x={item.x} baseline={item.baseline} size={item.size} width={item.width}
              ascent={item.ascent} descent={item.descent} inkLeft={item.inkLeft} progress={progress} clipId={`${uid}-${cue.id}-${item.word.id}-native`} />
            : item.letters.map(({ glyph, x }, letterIndex) => <g key={letterIndex}
              transform={`translate(${item.x + (x - item.inkLeft) * item.size / 1000} ${item.baseline}) scale(${item.size / 1000})`}>
              <WrittenGlyph glyph={glyph} progress={clamp01(progress * (count * .86 + .14) - letterIndex * .86)}
                maskId={`${uid}-${cue.id}-${item.word.id}-${letterIndex}`} />
            </g>)}
            </g>
            {underlineHere && draw > 0 ? <g fill="none" stroke={underline} strokeLinecap="round" strokeLinejoin="round">
              <path d={`M ${lineX + lineWidth * .06} ${lineY} Q ${lineX + lineWidth * .46} ${lineY - item.size * .08} ${lineX + lineWidth * .94} ${lineY + item.size * .015}`}
                strokeWidth={2.8} pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - draw} />
              <path d={`M ${lineX + lineWidth * .23} ${lineY + item.size * .055} Q ${lineX + lineWidth * .5} ${lineY + item.size * .025} ${lineX + lineWidth * .79} ${lineY + item.size * .065}`}
                strokeWidth={1.6} opacity={.8} pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - ease((draw - .25) / .75)} />
            </g> : null}
          </g>;
        })}
      </g>
    </svg> : null}
  </AbsoluteFill>;
};

export const resolveBecomesNotesMetadata = ({ props }: { props: BecomesNotesProps }) => {
  const source = props.sourceConfig ?? DEFAULT_SOURCE;
  const { words } = normalizeWords(source);
  const duration = Math.max(source.durationMs ?? 0, ...words.map(word => word.endMs + 260), 1000);
  return { fps: 30, durationInFrames: Math.ceil(duration * 30 / 1000) };
};
